-- ===== ТЕЛЕПОРТ + ПОВОРОТ + БЕГ (Velocity) + ПРЫЖОК =====
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")
local player = Players.LocalPlayer
local char = player.Character or player.CharacterAdded:Wait()
local rootPart = char:WaitForChild("HumanoidRootPart")
local humanoid = char:WaitForChild("Humanoid")

-- Парсим точки
local points = {}
for line in rawData:gmatch("[^\n]+") do
    if line:match("^%d+") then
        local parts = {}
        for p in line:gmatch("[^|]+") do table.insert(parts, p) end
        local x = tonumber(parts[2])
        local y = tonumber(parts[3])
        local z = tonumber(parts[4])
        local angle = tonumber(parts[6]) or 0
        local run = (parts[8] == "true")
        local jump = (parts[9] == "true")
        if x and y and z then
            table.insert(points, {
                pos = Vector3.new(x, y, z),
                angle = angle,
                run = run,
                jump = jump
            })
        end
    end
end

print("Загружено точек: " .. #points)
if #points == 0 then return end

local index = 1
local playing = true

RunService.RenderStepped:Connect(function()
    if not playing then return end
    if not char or not rootPart or humanoid.Health <= 0 then
        playing = false
        return
    end
    if index > #points then
        print("Готово!")
        playing = false
        return
    end
    
    local p = points[index]
    
    -- Телепорт + поворот
    rootPart.CFrame = CFrame.new(p.pos) * CFrame.Angles(0, math.rad(p.angle), 0)
    
    -- БЕГ (через Velocity, как в твоём скрипте)
    if p.run then
        rootPart.Velocity = rootPart.CFrame.LookVector * 16  -- скорость бега
    else
        rootPart.Velocity = Vector3.new(0,0,0)
    end
    
    -- ПРЫЖОК (как в твоём скрипте)
    if p.jump then
        humanoid.Jump = true
    end
    
    index = index + 1
end)
